function simulationDefaults():array{return ['schema'=>2,'until'=>null,'available_count'=>null,'overtime_from'=>null,'overtime_until'=>null,'horizon_days'=>30,'scope'=>'portfolio','productivity_percent'=>100,'availability_percent'=>100,'overtime_minutes'=>0,'material_delay_days'=>0,'rework_percent'=>0,'price_percent'=>100,'direct_percent'=>100,'extra_cost_cents'=>0,'batch_percent'=>100,'mode'=>'unchanged','use_estimates'=>false,'order_changes'=>[],'worker_changes'=>[],'assignments'=>[]];}
function simulationSettings(array $raw,array $source):array{
 $s=simulationDefaults();$ranges=['horizon_days'=>[1,180],'productivity_percent'=>[30,200],'availability_percent'=>[0,100],'overtime_minutes'=>[0,180],'material_delay_days'=>[0,90],'rework_percent'=>[0,50],'price_percent'=>[0,200],'direct_percent'=>[0,300],'extra_cost_cents'=>[0,100000000000],'batch_percent'=>[10,500]];
 foreach($ranges as $f=>[$min,$max])if(array_key_exists($f,$raw))$s[$f]=numberField($raw,$f,$min,$max);if(isset($raw['scope']))$s['scope']=textField($raw,'scope',40,true);$ids=array_column($source['orders'],'id');if($s['scope']!=='portfolio'&&!in_array($s['scope'],$ids,true))fail('Выберите цель текущего предприятия');
 if(isset($raw['mode']))$s['mode']=textField($raw,'mode',20,true);if(!in_array($s['mode'],['unchanged','whole','nodes','flow'],true))fail('Неизвестная организация сценария');if(isset($raw['use_estimates'])&&!is_bool($raw['use_estimates']))fail('Выберите режим предварительных оценок');$s['use_estimates']=$raw['use_estimates']??false;
 $zone=new DateTimeZone($source['company']['passport']['timezone']);$from=(new DateTimeImmutable('@'.$source['as_of']))->setTimezone($zone)->setTime(0,0);
 if(!empty($raw['until'])){$until=dateField($raw,'until');$days=(int)$from->diff(new DateTimeImmutable($until,$zone))->format('%r%a');if($days<1||$days>180)fail('Выберите будущую дату в пределах 180 дней');$s['horizon_days']=$days;}$s['until']=$from->modify('+'.$s['horizon_days'].' days')->format('Y-m-d');
 $productive=productionAssemblyPeople($source['company']['passport']);if(isset($raw['available_count']))$s['available_count']=numberField($raw,'available_count',0,count($productive));
 $s['overtime_from']=!empty($raw['overtime_from'])?dateField($raw,'overtime_from'):$from->format('Y-m-d');$s['overtime_until']=!empty($raw['overtime_until'])?dateField($raw,'overtime_until'):$s['until'];if($s['overtime_minutes']&&($s['overtime_from']<$from->format('Y-m-d')||$s['overtime_until']<$s['overtime_from']||$s['overtime_until']>$s['until']))fail('Продление смены должно иметь даты внутри выбранного периода');
 $people=array_column($productive,null,'id');foreach($raw['worker_changes']??[] as $id=>$v){if(!isset($people[$id])||!is_array($v))fail('Участник сценария недоступен');$s['worker_changes'][$id]=['available'=>array_key_exists('available',$v)?(bool)$v['available']:true,'productivity_percent'=>numberField($v+['productivity_percent'=>100],'productivity_percent',30,200)];}
 foreach($raw['order_changes']??[] as $id=>$v){if(!in_array($id,$ids,true)||!is_array($v))fail('Цель сценария недоступна');$s['order_changes'][$id]=['priority'=>numberField($v+['priority'=>2],'priority',1,3),'start_delay_days'=>numberField($v+['start_delay_days'=>0],'start_delay_days',0,90),'price_percent'=>numberField($v+['price_percent'=>100],'price_percent',0,200),'direct_percent'=>numberField($v+['direct_percent'=>100],'direct_percent',0,300)];foreach(['seconds_per_product'=>[1,864000],'unit_price_cents'=>[0,1000000000],'unit_direct_cents'=>[0,1000000000]] as $field=>[$lo,$hi])if(isset($v[$field]))$s['order_changes'][$id][$field]=numberField($v,$field,$lo,$hi);}
 if(!is_array($raw['assignments']??[])||count($raw['assignments']??[])>100)fail('Слишком много назначений в сценарии');foreach($raw['assignments']??[] as $a){$orderId=textField($a,'order_id',32,true);$node=textField($a,'node_id',60,true);$worker=textField($a,'worker_id',60,true);$o=array_values(array_filter($source['orders'],fn($o)=>$o['id']===$orderId))[0]??null;if(!$o||!isset($people[$worker])||!in_array($node,array_column($o['route'],'node_id'),true))fail('Назначение не относится к выбранной технологии');$s['assignments'][]=['order_id'=>$orderId,'node_id'=>$node,'worker_id'=>$worker];}
 return $s;
}
function simulationCapture(array $c):array{
 [$orders,$tasks]=engineInputs($c);$records=[];$preparations=[];foreach($orders as $o){$records[$o['id']]=workspaceRecord($c,$o);$preparations[$o['id']]=preparationRecord($c,$o)??['revision'=>0,'state'=>$o['preparation']];}$plans=rows('SELECT * FROM plan_versions WHERE company_id=? ORDER BY version_no',[$c['id']]);foreach($plans as &$p){$p['snapshot']=decode($p['snapshot']);$p['approvals']=decode($p['approvals']);}unset($p);$observations=rows('SELECT * FROM economy_observations WHERE company_id=? ORDER BY order_id,revision DESC',[$c['id']]);foreach($observations as &$o)foreach(['revision','accepted_quantity','recognized_cents','direct_cents','labor_cents','common_cents'] as $f)$o[$f]=$o[$f]===null?null:(int)$o[$f];unset($o);
 $hash=hash('sha256',j([engineHash($c,$orders,$tasks),array_map(fn($o)=>[$o['id'],$o['revision']],$observations),$records,$preparations,array_map(fn($p)=>[$p['id'],$p['state']],$plans)]));return ['company'=>$c,'orders'=>$orders,'tasks'=>$tasks,'plans'=>$plans,'observations'=>$observations,'workspaces'=>$records,'preparations'=>$preparations,'source_hash'=>$hash,'as_of'=>intdiv(time(),60)*60];
}
function simulationCalculate(array $source,array $settings):array{
 $c=$source['company'];$orders=$source['orders'];$tasks=$source['tasks'];$overrides=[];$warnings=[];$estimated=0;$c['_workspace_records']=$source['workspaces'];$c['_preparation_records']=$source['preparations']??[];foreach($orders as $o)if(!isset($c['_preparation_records'][$o['id']]))$c['_preparation_records'][$o['id']]=['revision'=>0,'state'=>$o['preparation']??preparationDefault($c,$o)];$c['_simulation_now']=$source['as_of'];$c['_simulation']=$settings;
 $active=productionAssemblyPeople($c['passport']);usort($active,fn($a,$b)=>strcmp($a['id'],$b['id']));$available=$settings['available_count']??(int)floor(count($active)*$settings['availability_percent']/100);$keep=array_fill_keys(array_column(array_slice($active,0,$available),'id'),true);
 foreach($c['passport']['people'] as &$p){$change=$settings['worker_changes'][$p['id']]??null;$p['active']=($p['active']??false)&&($change?($change['available']??true):isset($keep[$p['id']]));}unset($p);$working=array_column(array_filter($c['passport']['people'],fn($p)=>$p['active']),'id');
 foreach($c['passport']['resources'] as &$r)if(!empty($r['worker'])&&!in_array($r['worker'],$working,true))$r['worker']='';unset($r);
 $shift=$c['passport']['shift'];if($settings['overtime_minutes']){$start=minuteOfDay($shift['start']);$end=minuteOfDay($shift['end']);if($end<=$start)$end+=1440;if($end-$start+$settings['overtime_minutes']>960)fail('Смена не может превышать 16 часов.');$c['passport']['shift']['scenario_overtime']=['minutes'=>$settings['overtime_minutes'],'from'=>$settings['overtime_from']??simulationDate($source['as_of'],$c['passport']['timezone']),'until'=>$settings['overtime_until']??simulationDate($source['as_of']+$settings['horizon_days']*86400,$c['passport']['timezone'])];}
 foreach($orders as &$o){
  $changes=$settings['order_changes'][$o['id']]??[];$o['_simulation_priority']=$changes['priority']??2;$record=$source['workspaces'][$o['id']]??null;$workspace=$record['state']??workspaceDefault($o);if(!$record)foreach($workspace['input']['variants'] as &$v)$v['ready']=$v['quantity'];unset($v);
  if($settings['mode']!=='unchanged'&&($settings['scope']==='portfolio'||$settings['scope']===$o['id']))$workspace['mode']=$settings['mode'];
  foreach($workspace['allocations'] as &$a)if(!empty($a['worker_id'])&&!in_array($a['worker_id'],$working,true))$a['worker_id']='';unset($a);foreach($workspace['node_workers'] as &$id)if(!in_array($id,$working,true))$id='';unset($id);$workspace['whole_workers']=array_values(array_intersect($workspace['whole_workers'],$working));foreach($settings['assignments'] as $a)if($a['order_id']===$o['id']){$workspace['mode']='nodes';$workspace['node_workers'][$a['node_id']]=$a['worker_id'];}
  $overrides[$o['id']]=$workspace;
  if($settings['use_estimates'])foreach($o['route'] as &$op)if($op['seconds']===null&&($op['estimated_seconds']??null)!==null){$op['seconds']=(int)$op['estimated_seconds'];$op['norm_reviewed']=true;$op['source']='Сценарная оценка, не утверждённая производственная норма';$estimated++;}unset($op);
  if(isset($changes['seconds_per_product'])){$sum=array_sum(array_column($o['route'],'seconds'));if($sum>0&&!in_array(null,array_column($o['route'],'seconds'),true)){foreach($o['route'] as &$operation)$operation['seconds']=max(1,(int)round($operation['seconds']*$changes['seconds_per_product']/$sum));unset($operation);}else $warnings[]='Не удалось применить время на изделие «'.$o['title'].'»: сначала заполните нормы всех операций.';}
  if(isset($changes['unit_price_cents'])){$o['price_cents']=$changes['unit_price_cents'];$o['price_basis']='unit';}
  if(isset($changes['unit_direct_cents'])){$o['expenses']=[['id'=>'scenario-direct','name'=>'Сценарная полная сумма прямых затрат, включая комплектацию','kind'=>'direct','cents'=>$changes['unit_direct_cents']*(int)$o['quantity']]];$o['_preparation_cost_unknown']=false;}
  $delay=$changes['start_delay_days']??0;if($delay){$d=new DateTimeImmutable(max($o['start_date'],date('Y-m-d',$source['as_of'])));$o['start_date']=$d->modify('+'.$delay.' days')->format('Y-m-d');}
  $pricePercent=$changes['price_percent']??$settings['price_percent'];if($o['price_cents']!==null)$o['price_cents']=roundedRatio((int)$o['price_cents'],$pricePercent,100);$costPercent=$changes['direct_percent']??$settings['direct_percent'];foreach($o['expenses'] as &$ex)$ex['cents']=roundedRatio((int)$ex['cents'],$costPercent,100);unset($ex);
 }unset($o);
 $plan=calculateWorkspacePlan($c,$orders,$tasks,'deadline',$overrides);
 foreach($orders as $o){$id=$o['id'];if(!empty($plan['decision_summary'][$id]['errors'])){$plan['economy'][$id]['cost_cents']=null;$plan['economy'][$id]['unit_cents']=null;$plan['economy'][$id]['result_cents']=null;}
  $accepted=0;foreach($tasks as $t)if($t['order_id']===$id&&$t['is_final'])$accepted+=(int)$t['accepted'];$remaining=max(0,(int)$o['quantity']-$accepted);$extra=$remaining?roundedRatio($settings['extra_cost_cents'],(int)$o['quantity'],max(1,array_sum(array_column($orders,'quantity')))):0;
  if($extra&&$plan['economy'][$id]['cost_cents']!==null){$adjusted=roundedRatio($extra,(int)$o['quantity'],max(1,$remaining));$plan['economy'][$id]['cost_cents']+=$adjusted;$plan['economy'][$id]['direct_cents']+=$adjusted;$plan['economy'][$id]['unit_cents']=roundedRatio($plan['economy'][$id]['cost_cents'],1,(int)$o['quantity']);$value=$plan['economy'][$id]['value_cents'];$plan['economy'][$id]['result_cents']=$value===null?null:$value-$plan['economy'][$id]['cost_cents'];}
 }
 if($estimated)$warnings[]='Временно использованы '.$estimated.' непроверенных оценок времени. Такой прогноз условный и не утверждает нормы.';
 if($available<count($active))$warnings[]='Для новых работ оставлены '.count($working).' исполнителей сборки. Имена выбранных людей доступны в условиях; начатые задания сохраняются.';
 if($settings['overtime_minutes'])$warnings[]='Продление смены учитывается в календаре. Повышенная ставка сверхурочного труда не задана: результат без этой доплаты; внесите её в дополнительные расходы.';

 $plan['_sim_orders']=$orders;$plan['_sim_warnings']=$warnings;$plan['_sim_estimated']=$estimated;return $plan;
}
function simulationDate(int $stamp,string $zone):string{return (new DateTimeImmutable('@'.$stamp))->setTimezone(new DateTimeZone($zone))->format('Y-m-d');}
function simulationSummary(array $source,array $base,array $scenario,array $settings):array{
 $zone=$source['company']['passport']['timezone'];$from=simulationDate($source['as_of'],$zone);$until=(new DateTimeImmutable($from,new DateTimeZone($zone)))->modify('+'.$settings['horizon_days'].' days')->setTime(23,59,59);$end=$until->getTimestamp();$selected=$settings['scope']==='portfolio'?$source['orders']:array_values(array_filter($source['orders'],fn($o)=>$o['id']===$settings['scope']));$ids=array_column($selected,'id');
 $filtered=fn($plan)=>array_values(array_filter($plan['_sim_orders'],fn($o)=>in_array($o['id'],$ids,true)));$f=financeRollup($filtered($scenario),$source['plans'],$source['tasks'],$source['observations'],$scenario['economy']);$bf=financeRollup($filtered($base),$source['plans'],$source['tasks'],$source['observations'],$base['economy']);$fr=array_column($f['rows'],null,'order_id');$br=array_column($bf['rows'],null,'order_id');$rows=[];
 foreach($selected as $o){$id=$o['id'];$summary=$scenario['decision_summary'][$id]??[];$ec=$scenario['economy'][$id]??[];$accepted=array_sum(array_column(array_filter($source['tasks'],fn($t)=>$t['order_id']===$id&&$t['is_final']),'accepted'));$accepted=min((int)$o['quantity'],(int)$accepted);$finish=$summary['finish']??null;
  $through=function($plan,$limit)use($id,$o,$accepted,$zone){$n=0;foreach($plan['schedule'] as $t)if($t['order_id']===$id&&$t['is_final']&&plannerTime($t['end'],$zone)<=$limit)$n+=$t['quantity'];return min((int)$o['quantity'],max($accepted,$n));};
  $byHorizon=empty($summary['errors'])?$through($scenario,$end):null;$rows[]=['id'=>$id,'title'=>$o['title'],'mode'=>$o['mode'],'quantity'=>(int)$o['quantity'],'accepted'=>$accepted,'by_horizon'=>$byHorizon,'deadline'=>$o['deadline'],'finish'=>$finish,'baseline_finish'=>$base['decision_summary'][$id]['finish']??null,'late'=>$finish?substr($finish,0,10)>$o['deadline']:null,'result_cents'=>$fr[$id]['forecast_cents']??null,'expected_cents'=>$fr[$id]['expected_cents']??null,'actual_cents'=>$fr[$id]['actual_cents']??null,'unit_cents'=>$ec['unit_cents']??null,'errors'=>$summary['errors']??[],'hypothetical'=>$settings['use_estimates']];
 }
 $curve=[];for($day=0;$day<=$settings['horizon_days'];$day++){$limit=(new DateTimeImmutable($from,new DateTimeZone($zone)))->modify('+'.$day.' days')->setTime(23,59,59)->getTimestamp();$quantities=['base'=>0,'scenario'=>0];$values=['base'=>0,'scenario'=>0];$known=['base'=>true,'scenario'=>true];foreach(['base'=>$base,'scenario'=>$scenario] as $kind=>$plan){$map=$kind==='base'?$br:$fr;foreach($selected as $o){$n=0;foreach($plan['schedule'] as $t)if($t['order_id']===$o['id']&&$t['is_final']&&plannerTime($t['end'],$zone)<=$limit)$n+=$t['quantity'];$n=min((int)$o['quantity'],$n);$quantities[$kind]+=$n;if($o['mode']==='CONTRACT'){$v=$map[$o['id']]['forecast_cents']??null;if($v===null)$known[$kind]=false;elseif($n)$values[$kind]+=moneyShare($v,$n,(int)$o['quantity'])??0;}}}$curve[]=['date'=>simulationDate($limit,$zone),'baseline_quantity'=>$base['status']==='feasible'?$quantities['base']:null,'scenario_quantity'=>$scenario['status']==='feasible'?$quantities['scenario']:null,'baseline_cents'=>$known['base']&&$base['status']==='feasible'?$values['base']:null,'scenario_cents'=>$known['scenario']&&$scenario['status']==='feasible'?$values['scenario']:null];}
 $workers=[];foreach(productionAssemblyPeople($source['company']['passport']) as $person){$seconds=0;$baseSeconds=0;foreach($scenario['schedule'] as $t)if($t['worker_id']===$person['id']&&in_array($t['order_id'],$ids,true)&&!$t['pinned']){foreach($t['slots']??[[$t['start'],$t['end']]] as [$a,$b])$seconds+=max(0,min($end,plannerTime($b,$zone))-max($source['as_of'],plannerTime($a,$zone)));}foreach($base['schedule'] as $t)if($t['worker_id']===$person['id']&&in_array($t['order_id'],$ids,true)&&!$t['pinned']){foreach($t['slots']??[[$t['start'],$t['end']]] as [$a,$b])$baseSeconds+=max(0,min($end,plannerTime($b,$zone))-max($source['as_of'],plannerTime($a,$zone)));}$workers[]=['id'=>$person['id'],'name'=>$person['name'],'hours'=>round($seconds/3600,1),'baseline_hours'=>round($baseSeconds/3600,1),'available'=>array_column($scenario['people_snapshot'],null,'id')[$person['id']]['active']??false,'skills'=>$person['skills']];}
 $last=end($curve);$finishDates=array_filter(array_column($rows,'finish'));$full=count($finishDates)===count($rows)&&$rows;$finish=$full?max($finishDates):null;$warnings=array_values(array_unique(array_merge($scenario['warnings'],$scenario['_sim_warnings'],['Производственный результат не включает продажи собственных изделий и финансы всей компании.','Затраты остатка оценены по средней калькуляции; подтверждённый факт принятой части сохраняется.','Прогноз использует конечных людей, оборудование и календарь; оптимум не заявляется.'])));
 return ['version'=>SIMULATION_VERSION,'source_hash'=>$source['source_hash'],'as_of'=>date('c',$source['as_of']),'from'=>$from,'until'=>$until->format('Y-m-d'),'settings'=>$settings,'status'=>$scenario['status']==='feasible'?($scenario['_sim_estimated']?'conditional':'feasible'):'incomplete','summary'=>['expected_cents'=>$bf['expected_cents'],'baseline_forecast_cents'=>$bf['forecast_cents'],'actual_cents'=>$f['actual_cents'],'forecast_cents'=>$f['forecast_cents'],'period_forecast_cents'=>$last['scenario_cents'],'period_baseline_cents'=>$last['baseline_cents'],'finish'=>$finish,'baseline_finish'=>$base['finish'],'quantity'=>array_sum(array_column($selected,'quantity')),'accepted'=>array_sum(array_column($rows,'accepted')),'by_horizon'=>$last['scenario_quantity'],'late_orders'=>count(array_filter($rows,fn($r)=>$r['late']===true)),'incomplete_orders'=>count(array_filter($rows,fn($r)=>$r['errors']))],'orders'=>$rows,'workers'=>$workers,'curve'=>$curve,'warnings'=>$warnings,'errors'=>$scenario['errors'],'schedule'=>array_values(array_filter($scenario['schedule'],fn($t)=>in_array($t['order_id'],$ids,true)&&($t['pinned']||empty($scenario['decision_summary'][$t['order_id']]['errors'])))),'impacted_orders'=>array_map(fn($o)=>['id'=>$o['id'],'title'=>$o['title'],'finish'=>$scenario['decision_summary'][$o['id']]['finish']??null],array_values(array_filter($source['orders'],fn($o)=>!in_array($o['id'],$ids,true))))];
}

/** The target date defines the horizon; finishing the entire portfolio is a separate objective. */
function simulationTargetVerdict(array $result,array $target,bool $hasNewGoals=false):string{
 if($result['status']==='incomplete'||$hasNewGoals)return 'needs_data';$s=$result['summary'];$met=[];
 foreach(['result_cents'=>'period_forecast_cents','quantity'=>'by_horizon'] as $goal=>$metric)if($target[$goal]!==null){if(($s[$metric]??null)===null)return 'needs_data';$met[]=$s[$metric]>=$target[$goal];}
 if($target['deadline']!==null&&$target['result_cents']===null&&$target['quantity']===null){if(($s['finish']??null)===null)return 'needs_data';$met[]=substr($s['finish'],0,10)<=$target['deadline'];}
 return !$met?'compare':(in_array(false,$met,true)?'not_reached':'reached');
}
